<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Struk {{ $transaction->ticket_number }}</title><style>body{font-family:Arial,sans-serif;background:#f4f6f3;padding:30px;color:#172527}.receipt{background:#fff;width:min(440px,100%);margin:auto;padding:28px;border:1px solid #dce5e0}.head{text-align:center;border-bottom:2px solid #16735b;padding-bottom:18px}.head h1{margin:0;color:#16735b}.row{display:flex;justify-content:space-between;padding:12px 0;border-bottom:1px dashed #dce5e0}.total{font-size:23px;font-weight:bold;color:#16735b}.print{margin:20px auto 0;display:block;background:#16735b;color:white;border:0;padding:11px 16px;border-radius:6px}@media print{body{background:#fff;padding:0}.print{display:none}}</style></head><body><article class="receipt"><div class="head"><h1>ParkirKita</h1><p>Struk transaksi parkir</p></div><div class="row"><span>No. tiket</span><strong>{{ $transaction->ticket_number }}</strong></div><div class="row"><span>Nomor polisi</span><strong>{{ $transaction->plate_number }}</strong></div><div class="row"><span>Area</span><span>{{ $transaction->area->name }}</span></div><div class="row"><span>Masuk</span><span>{{ $transaction->entry_at->format('d/m/Y H:i') }}</span></div><div class="row"><span>Keluar</span><span>{{ $transaction->exit_at?->format('d/m/Y H:i') }}</span></div><div class="row total"><span>Total</span><span>Rp {{ number_format($transaction->total_amount,0,',','.') }}</span></div><button class="print" onclick="window.print()">Cetak struk</button></article></body></html>